arguments.manager_and_device_options:
{%- set recs = vars.steps.find_devices_with_manager -%}
{%- set src = [] -%}
{%- set mdb = [] -%}

{%- for s in recs -%}
  {%- set n = s -%}
  {%- set m = s.ztpfManagers.name
                  + " ("
                  + s.ztpfManagers.firmware.split(' ')[0]
                  + ")"
  -%}
  {%- set d = s.name
                  + " ("
                  + s.platform
                  + ")"
  -%}
  {%- do n.update({
    "_option_mgr":m,
    "_option_dev":d
  }) -%}
  {%- do src.append(n) -%}
{%- endfor -%}

{%- set managers = src|json_query('[]._option_mgr')|unique -%}
{%- for m in managers|sort  -%}
  {%- set o = {} -%}
  {%- do o.update({
    "value":m,
    "options": src 
        | json_query('[?_option_mgr==`{}`]'.format(m))
        | json_query('[]._option_dev') | sort
  }) -%}
  {%- do mdb.append(o) -%}
{%- endfor -%}

{
"opts": {{mdb}},
 "src": {{src}}
}

